import Vue from 'vue'
import Router from 'vue-router'
import Home from '@/pages/Home'
import Business from '@/pages/BusinessModel'
import Product from '@/pages/ProductService'
import Elements from '@/pages/Elements'

Vue.use(Router)

export default new Router({
  routes: [
    {
      path: '/',
      name: 'home',
      component: Home
    },
    {
      path: '/product',
      name: 'product',
      component: Product
    },
    {
      path: '/business',
      name: 'business',
      component: Business
    },
    {
      path: '/elements',
      name: 'elements',
      component: Elements
    }
  ]
})



